DECLARE @no varchar(31)=?,@name nvarchar(642)=?,@class bigint=?,@s1 varchar(2)=?,@s2 varchar(2)=?,@s3 varchar(2)=?,@s4 varchar(2)=?; SELECT COUNT_BIG(*) FROM (SELECT TOP (10001) s.student_id FROM dbo.m_student s LEFT JOIN dbo.m_class c ON c.class_id=s.class_id WHERE s.is_deleted=0 AND (@no IS NULL OR s.student_no LIKE @no ESCAPE '!') AND (@name IS NULL OR s.name_key LIKE @name ESCAPE '!') AND (@class IS NULL OR s.class_id=@class) AND ((@s1 IS NULL AND @s2 IS NULL AND @s3 IS NULL AND @s4 IS NULL) OR s.enrollment_status_code IN (@s1,@s2,@s3,@s4))) limited;
